export function createWorkbook(db, name) {
  const id = newId('wb');
  const worksheetId = newId('ws');
  const at = nowIso();
  db.transaction(() => {
    db.prepare('INSERT INTO workbooks (id, name, created_at, updated_at) VALUES (?, ?, ?, ?)').run(
      id,
      name,
      at,
      at,
    );
    db.prepare(
      `INSERT INTO worksheets (id, workbook_id, name, position, row_count, col_count, last_active, last_selection)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    ).run(
      worksheetId,
      id,
      'Sheet1',
      0,
      DEFAULT_ROW_COUNT,
      DEFAULT_COL_COUNT,
      1,
      JSON.stringify(DEFAULT_SELECTION),
    );
  })();
  const snapshot = getWorkbookSnapshot(db, id);
  if (!snapshot) throw new Error('Failed to create workbook');
  return snapshot;
}

